test('worker row-store truncation removes only the uncommitted tail', async () => {
    const { api } = loadApi();
    const worker = new MemoryWorker();
    const store = await api.createRowStore({ workerFactory: () => worker });
    await store.append([[null], [null], [null]]);
    assert.equal(typeof store.truncate, 'function');
    assert.equal(await store.truncate(2), 2);
    assert.equal(await store.count(), 2);
    assert.equal((await store.read(0, 5)).length, 2);
    await assert.rejects(store.truncate(3), /count|range|truncate/i);
    await assert.rejects(store.truncate(-1), /count|range|truncate/i);
    await store.dispose();
});

test('cancelled append retains the committed batch and ignores a late terminal record', async () => {
    let finishRead;
    const partial = batch([2], 2, true).slice(0, -1);
    let readIndex = 0;
    const pendingResponse = {
        ok: true, status: 200,
        body: { getReader() { return {
            async read() {
                if (readIndex < partial.length) return {
                    done: false, value: new TextEncoder().encode(JSON.stringify(partial[readIndex++]) + '\n')
                };
                return new Promise(resolve => { finishRead = resolve; });
            },
            async cancel() {}
        }; } }
    };
    const current = execution({ responses: [batch([0, 1], 0, true), () => pendingResponse, batch([2, 3], 2, false)] });
    current.controller.submit();
    await settle();
    assert.equal(typeof current.controller.loadMore, 'function');
    current.controller.loadMore();
    await settle();
    assert.equal(current.controller.hasActiveRequest(), true);
    assert.equal(current.target.querySelector('.query-result-load-more').disabled, true);
    current.controller.cancel();
    await settle();
    assert.deepEqual(current.workers[0].rows.map(row => row[0].value), ['0', '1']);
    finishRead({ done: false, value: new TextEncoder().encode(JSON.stringify(batch([], 3, false).at(-1)) + '\n') });
    await settle();
    current.controller.loadMore();
    await settle();
    assert.equal(current.requests[2].init.body.get('batch-offset'), '2');
    assert.deepEqual(current.workers[0].rows.map(row => row[0].value), ['0', '1', '2', '3']);
    current.controller.dispose();
});

test('late old execution response cannot replace or append to a reexecution', async () => {
    let release;
    const current = execution({ responses: [
        () => new Promise(resolve => { release = resolve; }), batch([9], 0, false)
    ] });
    current.controller.submit();
    current.controller.submit();
    await settle();
    release(response(batch([0, 1], 0, true)));
    await settle();
    assert.deepEqual(current.workers.at(-1).rows.map(row => row[0].value), ['9']);
    assert.equal(current.target.querySelector('.query-result-load-more').hidden, true);
    current.controller.dispose();
});

test('blank-node identity stays batch scoped even inside RDF triple terms', async () => {
    const records = offset => {
        const result = batch([], offset, offset === 0);
        result[4].values = [[{ kind: 'triple',
            subject: { kind: 'bnode', value: 'same-label' },
            predicate: { kind: 'iri', value: 'urn:example:p' },
            object: { kind: 'literal', value: 'a long lexical value', language: 'en' }
        }]];
        Object.assign(result.at(-1).metadata, { 'result-limit': 1,
            'result-batch-count': 1, 'result-next-offset': offset + 1 });
        return result;
    };
    const current = execution({ controls: { 'batch-size': '1' }, responses: [records(0), records(1)] });
    current.controller.submit();
    await settle();
    assert.equal(typeof current.controller.loadMore, 'function');
    current.controller.loadMore();
    await settle();
    const rows = current.workers[0].rows;
    assert.equal(rows[0][0].subject.value, 'same-label');
    assert.equal(rows[1][0].subject.value, 'same-label');
    assert.ok(rows[0][0].subject.scope, 'blank-node identities need an execution response scope');
    assert.notEqual(rows[0][0].subject.scope, rows[1][0].subject.scope);
    assert.deepEqual(JSON.parse(JSON.stringify(rows[0][0].object)),
        { kind: 'literal', value: 'a long lexical value', language: 'en' });
    current.controller.dispose();
});

test('records browse the loaded store by scrolling with bounded DOM and no paging buttons', async () => {
    const { api, document } = loadApi();
    const target = document.createElement('section');
    document.body.appendChild(target);
    const rows = Array.from({ length: 30 }, (_, index) => [{ kind: 'literal', value: String(index) }]);
    const renderer = new api.QueryResultRenderer(target, {
        maxDomRows: 8, initialLayout: 'records', rowStore: {
            async append() { return rows.length; }, async read(start, count) { return rows.slice(start, start + count); },
            async count() { return rows.length; }, async dispose() {}
        }
    });
    const records = target.querySelector('.query-result-records');
    records.clientHeight = 96;
    for (const record of batch([], 0, false).slice(0, 4)) await renderer.accept(record);
    await renderer.accept({ type: 'rows', values: rows });
    await renderer.accept({ type: 'end', metadata: { 'total-result-count': 30 } });
    assert.equal(target.querySelectorAll('button').some(button => /Next|Previous/.test(button.textContent)), false);
    records.scrollTop = 720;
    records.trigger('scroll');
    await settle();
    const indexes = records.children.map(child => child.getAttribute('data-query-record-index'))
        .filter(value => value !== undefined).map(Number);
    assert.ok(indexes.includes(29), 'the last loaded record is reachable without a query request');
    assert.ok(indexes.length <= 8);
    renderer.dispose();
});

test('logical scroll coordinates retain first middle and last windows beyond browser pixel limits', () => {
    const { api } = loadApi();
    assert.equal(typeof api.ResultScrollCoordinates, 'function');
    const coordinates = new api.ResultScrollCoordinates(1000000);
    coordinates.update(100000000, 500);
    assert.equal(coordinates.physicalHeight, 1000000);
    assert.equal(coordinates.logicalOffset(0), 0);
    assert.equal(coordinates.logicalOffset(999500), 99999500);
    const middle = coordinates.physicalOffset(50000000);
    assert.ok(Math.abs(coordinates.logicalOffset(middle) - 50000000) < 0.01);
    const spacers = coordinates.spacers(49999800, 1200, middle);
    assert.ok(Math.abs(spacers.top + 1200 + spacers.bottom - coordinates.physicalHeight) < 0.01);
    assert.ok(Math.abs(middle - spacers.top - 200) < 0.01,
        'visible rows keep their real height while only offscreen coordinates are compressed');
});

