test('result downloads retain the executed query and their separate explicit limit', async () => {
    const current = execution();
    current.controller.submit();
    await settle();
    const original = current.controls.query.value;
    current.controls.query.value = 'SELECT ?edited WHERE {}';
    current.controls.infer.value = 'false';
    const createElement = current.document.createElement.bind(current.document);
    let downloaded;
    current.document.createElement = name => {
        const node = createElement(name);
        if (name === 'form') node.submit = () => {
            downloaded = new URLSearchParams();
            for (const control of node.formControls) downloaded.append(control.name, control.value);
        };
        return node;
    };
    const limit = current.target.querySelectorAll('select').find(control => control.name === 'download_limit');
    limit.value = '2';
    current.target.querySelector('.query-result-download-button').trigger('click');
    assert.ok(downloaded);
    assert.equal(downloaded.get('query'), original);
    assert.equal(downloaded.get('infer'), 'true');
    assert.equal(downloaded.get('download_limit'), '2');
    assert.equal(downloaded.has('batch-size'), false);
    assert.equal(downloaded.has('batch-offset'), false);
    current.controller.dispose();
});

test('progressive row writes coalesce visible rendering rather than rereading for every wire record', async () => {
    const { api, document, window } = loadApi();
    const frames = [];
    window.requestAnimationFrame = callback => { frames.push(callback); };
    const target = document.createElement('section');
    document.body.appendChild(target);
    let count = 0;
    let reads = 0;
    const renderer = new api.QueryResultRenderer(target, {
        batched: true, requestedLimit: 3200, rowStore: {
            async append(rows) { count += rows.length; return count; },
            async read(start, size) { reads++; return Array.from({ length: size }, () => [null]); },
            async count() { return count; }, async truncate(next) { count = next; return count; }, async dispose() {}
        }
    });
    renderer.beginBatch(0);
    await renderer.accept({ type: 'head', version: 1 });
    await renderer.accept({ type: 'view', id: 'tuple' });
    await renderer.accept({ type: 'vars', values: ['value'] });
    for (let index = 0; index < 100; index++) {
        await renderer.accept({ type: 'rows', values: Array.from({ length: 32 }, () => [null]) });
    }
    await renderer.accept({ type: 'end', metadata: {
        'result-offset': 0, 'result-limit': 3200, 'result-batch-count': 3200,
        'result-has-more': false, 'result-next-offset': 3200
    } });
    assert.equal(count, 3200);
    assert.ok(reads <= 3, `received records must not each reread the visible window; saw ${reads} reads`);
    assert.ok(frames.length <= 1, 'pending rendering is coalesced into one animation frame');
    renderer.dispose();
});

for (const layout of ['table', 'records']) {
  for (const overflow of ['clamp', 'collapse']) {
    test(`${layout} ${overflow} scroll capacity keeps wheel and keyboard row access`, async () => {
        const { api, document } = loadApi();
        const createElement = document.createElement.bind(document);
        document.createElement = name => {
            const element = createElement(name);
            element.getBoundingClientRect = () => {
                const requested = parseFloat(element.style.height) || 0;
                return { top: 0, left: 0, width: 0,
                    height: overflow === 'collapse' && requested > 1000 ? 0 : Math.min(1000, requested) };
            };
            if (name === 'div') Object.defineProperty(element, 'scrollHeight', { get() {
                if (this.style.overflow !== 'scroll' || !this.children.length) return 0;
                const content = this.children[0];
                const target = content.tagName === 'TABLE' ? content.children[0].children[0].children[0] : content;
                const requested = parseFloat(target.style.height) || 0;
                return Math.max(1, overflow === 'collapse' && requested > 1000 ? 0 : Math.min(1000, requested));
            } });
            return element;
        };
        const target = document.createElement('section');
        document.body.appendChild(target);
        const rows = Array.from({ length: 3000 }, () => [null]);
        const reads = [];
        const renderer = new api.QueryResultRenderer(target, {
            initialLayout: layout, maxDomRows: 8, rowStore: {
                async append() { return rows.length; }, async read(start, count) {
                    reads.push([start, count]);
                    return rows.slice(start, start + count);
                },
                async count() { return rows.length; }, async truncate() {}, async dispose() {}
            }
        });
        const scrollport = layout === 'table' ? renderer.tableWrap : target.querySelector('.query-result-records');
        scrollport.clientHeight = 96;
        for (const record of batch([], 0, false).slice(0, 4)) await renderer.accept(record);
        await renderer.accept({ type: 'rows', values: rows });
        await renderer.accept({ type: 'end', metadata: { 'total-result-count': rows.length } });
        assert.equal(reads[reads.length - 1][0], 0, 'the initial window should start at the first loaded row');
        const spacers = scrollport.querySelectorAll('[data-query-spacer]');
        assert.ok(spacers.reduce((sum, spacer) => sum + (parseFloat(spacer.style.height) || 0), 0) > 0,
            'hidden loaded rows need usable physical scroll extent after oversized blocks collapse');
        const wheel = scrollport.trigger('wheel', { deltaY: 20000, deltaMode: 0 });
        assert.equal(wheel.defaultPrevented, true, 'wheel steps must retain natural logical distances above the pixel cap');
        await settle();
        const beforeWheel = reads[reads.length - 1];
        assert.ok(beforeWheel[0] >= 800 && beforeWheel[0] < 1200,
            `wheel scrolling should request a middle virtual window; got ${beforeWheel}`);
        const nextWheel = scrollport.trigger('wheel', { deltaY: 240, deltaMode: 0 });
        assert.equal(nextWheel.defaultPrevented, true);
        await settle();
        const afterWheel = reads[reads.length - 1];
        assert.ok(afterWheel[0] > beforeWheel[0],
            'wheel scrolling should advance the virtualized window through loaded rows');
        const end = scrollport.trigger('keydown', { key: 'End' });
        assert.equal(end.defaultPrevented, true, 'End should move the native result scrollport to its loaded tail');
        await settle();
        const lastWindow = reads[reads.length - 1];
        assert.ok(lastWindow[0] <= 2999 && lastWindow[0] + lastWindow[1] > 2999,
            'End should request a virtual window containing the last loaded row');
        const home = scrollport.trigger('keydown', { key: 'Home' });
        assert.equal(home.defaultPrevented, true, 'Home should return to the start of the loaded result');
        await settle();
        assert.equal(reads[reads.length - 1][0], 0, 'Home should request the first loaded row window');
        renderer.dispose();
    });
  }
}
